static const uint8_t segmentRegnums[SEG_OVERRIDE_max] = {
        0,        // SEG_OVERRIDE_NONE
        X86_CS,
        X86_SS,
        X86_DS,
        X86_ES,
        X86_FS,
        X86_GS
